import{_ as t,o as r,c as a,a0 as e}from"./chunks/framework.DQOulFGV.js";const u=JSON.parse('{"title":"快速開始","description":"","frontmatter":{},"headers":[],"relativePath":"zh-hant/guide/start.md","filePath":"zh-hant/guide/start.md"}'),n={name:"zh-hant/guide/start.md"};function l(s,o,i,d,g,c){return r(),a("div",null,[...o[0]||(o[0]=[e('<h1 id="快速開始" tabindex="-1">快速開始 <a class="header-anchor" href="#快速開始" aria-label="Permalink to &quot;快速開始&quot;">​</a></h1><p>歡迎使用 <strong>KernelEX</strong>！本章節將帶你快速瞭解環境要求、安裝授權流程以及如何執行你的第一個腳本。</p><hr><h2 id="📱-運行環境要求" tabindex="-1">📱 運行環境要求 <a class="header-anchor" href="#📱-運行環境要求" aria-label="Permalink to &quot;📱 運行環境要求&quot;">​</a></h2><p>在開始使用前，請確保你的 Android 裝置滿足以下條件：</p><ul><li><strong>作業系統</strong>：Android 8.0 (API 26) 及以上</li><li><strong>裝置架構</strong>：<code>arm64-v8a</code>、<code>armeabi-v7a</code>、<code>x86_64</code></li><li><strong>ROOT 方案</strong>：已安裝並啟用 <strong>Magisk</strong>、<strong>KernelSU</strong> 或 <strong>APatch</strong> 超級使用者管理器</li><li><strong>儲存權限</strong>：Android 11+ 裝置需授予「管理所有檔案」權限（用於讀取/匯入外部儲存腳本）</li></ul><hr><h2 id="🔑-權限設定指引" tabindex="-1">🔑 權限設定指引 <a class="header-anchor" href="#🔑-權限設定指引" aria-label="Permalink to &quot;🔑 權限設定指引&quot;">​</a></h2><p>首次開啟 KernelEX 時，應用將進入**權限檢查門（Permission Gate）**引導介面：</p><ol><li><strong>ROOT 超級使用者權限</strong>：點擊「請求 ROOT 授權」，在彈出的授權管理器（Magisk/KernelSU/APatch）中點擊「永久允許」。</li><li><strong>所有檔案存取權限</strong>：點擊前往系統設定，開啟「授予所有檔案管理權限」，以便應用讀取外部儲存中的腳本。</li><li><strong>忽略電池最佳化（建議開啟）</strong>：點擊申請加入系統電池白名單，防止後台長時間執行繁重腳本時被系統行程清理。</li></ol><div class="tip custom-block"><p class="custom-block-title">自動感知</p><p>所有必要權限就緒後，頁面將自動感知並進入軟體主介面，無需反覆手動重新整理。</p></div><hr><h2 id="🚀-執行你的第一個腳本" tabindex="-1">🚀 執行你的第一個腳本 <a class="header-anchor" href="#🚀-執行你的第一個腳本" aria-label="Permalink to &quot;🚀 執行你的第一個腳本&quot;">​</a></h2><p>KernelEX 提供多種便捷的檔案執行方式：</p><h3 id="方式-1-首頁路徑輸入與選擇" tabindex="-1">方式 1：首頁路徑輸入與選擇 <a class="header-anchor" href="#方式-1-首頁路徑輸入與選擇" aria-label="Permalink to &quot;方式 1：首頁路徑輸入與選擇&quot;">​</a></h3><ol><li>開啟應用，進入底欄「<strong>首頁</strong>」；</li><li>在輸入框直接輸入腳本絕對路徑，或點擊「<strong>從檔案管理器選擇</strong>」挑選 <code>.sh</code> 或 <code>.so</code> 檔案；</li><li>點擊「<strong>立即執行</strong>」，應用將自動跳轉到「<strong>終端</strong>」頁面並即時列印輸出。</li></ol><h3 id="方式-2-工作區目錄一鍵執行" tabindex="-1">方式 2：工作區目錄一鍵執行 <a class="header-anchor" href="#方式-2-工作區目錄一鍵執行" aria-label="Permalink to &quot;方式 2：工作區目錄一鍵執行&quot;">​</a></h3><ol><li>將你的腳本或可執行檔案放入預設工作區目錄：<code>/data/adb/KernelEX/</code>；</li><li>在「首頁」下方卡片中點擊對應檔案即可直接選定或啟動。</li></ol><h3 id="方式-3-全盤檔案管理器長按新增" tabindex="-1">方式 3：全盤檔案管理器長按新增 <a class="header-anchor" href="#方式-3-全盤檔案管理器長按新增" aria-label="Permalink to &quot;方式 3：全盤檔案管理器長按新增&quot;">​</a></h3><ol><li>切換至底欄「<strong>檔案</strong>」頁面；</li><li>瀏覽至腳本所在目錄，長按目標檔案呼出操作選單；</li><li>選擇「<strong>新增到 KernelEX</strong>」，檔案將自動複製到工作區並自動設定 <code>chmod 777</code> 權限（若在設定中開啟了「新增後自動執行」，將立即開始運行）。</li></ol><hr><h2 id="💻-終端操作與控制" tabindex="-1">💻 終端操作與控制 <a class="header-anchor" href="#💻-終端操作與控制" aria-label="Permalink to &quot;💻 終端操作與控制&quot;">​</a></h2><p>進入「<strong>終端</strong>」頁面後，你可以進行以下操作：</p><ul><li><strong>傳送標準輸入（stdin）</strong>：如果腳本在等待使用者互動輸入（例如 <code>read -p &quot;請輸入: &quot;</code>），在底部輸入框輸入內容並點擊「傳送」或換行鍵即可。</li><li><strong>傳送中斷訊號（Ctrl+C）</strong>：點擊「<strong>中斷</strong>」按鈕向當前運行中的子行程傳送 <code>SIGINT</code>（<code>kill -2</code>）訊號。</li><li><strong>強制結束任務</strong>：點擊「<strong>結束行程</strong>」按鈕強行終止任務（<code>kill -9</code>）。</li><li><strong>複製輸出</strong>：點擊頂部「<strong>複製輸出</strong>」一鍵複製控制台純文字日誌到剪貼簿。</li><li><strong>清屏與重跑</strong>：任務結束後點擊「<strong>清屏</strong>」重設控制台，或點擊「<strong>重新運行</strong>」再次執行上次任務。</li></ul>',24)])])}const p=t(n,[["render",l]]);export{u as __pageData,p as default};
